import java.util.*;
import java.io.*;

public class E {

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = reader.readLine().split(" ");
        int n = Integer.parseInt(parts[0]);
        long kt = Long.parseLong(parts[1]);

        if (kt >= n) {
            System.out.println(0);
            return;
        }

        int k = (int) kt;
        long MOD = 998244353L;
        long[] fact = new long[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = (fact[i - 1] * i) % MOD;
        }

        long result = 0;
        int c = n - k;
        for (int i = 0; i <= c; i++) {
            long comb = (fact[c] * modInverse(fact[i], MOD) % MOD) * modInverse(fact[c - i], MOD) % MOD;
            long power = modPow(c - i, n, MOD);
            long term = (comb * power) % MOD;
            if (i % 2 == 0) {
                result = (result + term) % MOD;
            } else {
                result = (result - term + MOD) % MOD;
            }
        }
        long totalComb = (fact[n] * modInverse(fact[n - k], MOD) % MOD) * modInverse(fact[k], MOD) % MOD;
        result = (result * totalComb) % MOD;
        if (k > 0) result = (result * 2) % MOD;
        System.out.println(result);
    }

    private static long modInverse(long a, long m) {
        return modPow(a, m - 2, m);
    }

    private static long modPow(long base, int exp, long m) {
        long res = 1;
        long b = base % m;
        int e = exp;
        while (e > 0) {
            if ((e & 1) == 1) {
                res = (res * b) % m;
            }
            b = (b * b) % m;
            e >>= 1;
        }
        return res;
    }
}
